// UserForm.js (ex-Register.js)

import React, { useState, useEffect } from "react";
import axios from "axios";
import { getBaseURL } from "../apiConfig";
import "./Register.scss";

function UserForm({ 
  mode = "register",         // "register" ou "update"
  userId,                    // l’ID de l’utilisateur connecté (si update)
  navigateToLoginPage 
}) {
  const [email, setEmail] = useState("");
  const [fname, setFname] = useState("");
  const [lname, setLname] = useState("");
  const [pass, setPass] = useState("");
  const [isAdmin, setAdmin] = useState("0");
  const [error, setError] = useState("");

  // ─────────────────────────────────────────────────────────────
  // 1) Charger l’utilisateur connecté si on est en mode "update"
  // ─────────────────────────────────────────────────────────────
  useEffect(() => {
    if (mode === "update" && userId) {
      // Récupérer les infos existantes de l’utilisateur
      axios
        .get(`${getBaseURL()}api/users/${userId}`)
        .then((res) => {
          const data = res.data;
          setEmail(data.email || "");
          setFname(data.fname || "");
          setLname(data.lname || "");
          setPass(""); // Ne jamais afficher le mot de passe réel
          setAdmin(data.isAdmin ? "1" : "0");
        })
        .catch((err) => {
          console.log("Error fetching user data for update:", err);
        });
    }
  }, [mode, userId]);

  // ─────────────────────────────────────────────────────────────
  // 2) Soumission du formulaire
  // ─────────────────────────────────────────────────────────────
  const handleSubmit = () => {
    if (!validateInputs()) return;

    if (mode === "register") {
      handleUserRegistration();
    } else if (mode === "update") {
      handleUserUpdate(); // Nouvelle fonction pour l’update
    }
  };

  // ─────────────────────────────────────────────────────────────
  // 3) Enregistrer un nouvel utilisateur
  // ─────────────────────────────────────────────────────────────
  const handleUserRegistration = () => {
    const newUser = {
      email,
      password: pass,
      isAdmin,
      fname,
      lname,
    };

    axios
      .post(`${getBaseURL()}api/users/register`, newUser)
      .then((res) => {
        console.log("User registered successfully");
        navigateToLoginPage && navigateToLoginPage(); 
      })
      .catch((err) => console.log("Sorry unable to add new user", err));
  };

  // ─────────────────────────────────────────────────────────────
  // 4) Mettre à jour l’utilisateur existant
  // ─────────────────────────────────────────────────────────────
  const handleUserUpdate = () => {
    const updatedUser = {
      email,
      // Le mot de passe est soit vide, soit un nouveau
      password: pass,
      isAdmin,
      fname,
      lname,
    };

    axios
      .put(`${getBaseURL()}api/users/update/${userId}`, updatedUser)
      .then((res) => {
        console.log("User updated successfully");
        // Faire quelque chose après la mise à jour : 
        // ex : naviguer vers la page d'accueil ou afficher un message
        alert("Profile updated successfully!");
      })
      .catch((err) => {
        console.log("Error updating user", err);
      });
  };

  // ─────────────────────────────────────────────────────────────
  // 5) Fonctions utilitaires
  // ─────────────────────────────────────────────────────────────
  const validateEmail = (email) => {
    const regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return regex.test(email);
  };
  const validatePassword = (password) => {
    // Si vous souhaitez permettre un mot de passe vide en mode "update"
    // (si l’utilisateur ne souhaite pas changer de mdp), on peut checker différemment
    if (mode === "update" && !password) return true;
    return password.length >= 6;
  };
  const validateInputs = () => {
    if (!validateEmail(email)) {
      setError("Please provide a valid email address.");
      return false;
    } else if (fname.trim() === "") {
      setError("Please provide your first name.");
      return false;
    } else if (lname.trim() === "") {
      setError("Please provide your last name.");
      return false;
    } else if (!validatePassword(pass)) {
      setError("Password must be at least 6 characters long (or empty in update mode).");
      return false;
    }
    setError("");
    return true;
  };
  const updateAdmin = (adminValue) => {
    setAdmin(adminValue);
  };

  // ─────────────────────────────────────────────────────────────
  // 6) Rendu
  // ─────────────────────────────────────────────────────────────
  return (
    <div className="register-container">
      <h1>{mode === "update" ? "Update Profile" : "Register"}</h1>
      <div>
        <label>E-Mail</label>
        <input
          type="text"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          // Désactiver si vous ne voulez pas changer l’email en update
          disabled={mode === "update" && Boolean(userId)}
        />
      </div>
      <div>
        <label>First Name</label>
        <input
          type="text"
          value={fname}
          onChange={(e) => setFname(e.target.value)}
        />
      </div>
      <div>
        <label>Last Name</label>
        <input
          type="text"
          value={lname}
          onChange={(e) => setLname(e.target.value)}
        />
      </div>
      <div>
        <label>Password</label>
        <input
          type="password"
          value={pass}
          onChange={(e) => setPass(e.target.value)}
          placeholder={
            mode === "update"
              ? "Leave empty to keep current password"
              : "Password"
          }
        />
      </div>
      {error && <div className="error-message">{error}</div>}
      <div className="radio-group">
        <input
          type="radio"
          id="customer"
          name="role"
          value="0"
          checked={isAdmin === "0"}
          onChange={() => updateAdmin("0")}
        />
        <label htmlFor="customer">Customer</label>
        <br />
        <input
          type="radio"
          id="admin"
          name="role"
          value="1"
          checked={isAdmin === "1"}
          onChange={() => updateAdmin("1")}
        />
        <label htmlFor="admin">Admin</label>
      </div>
      <div>
        <button onClick={handleSubmit}>
          {mode === "update" ? "Save" : "Register"}
        </button>
      </div>
      {/* 
        Optionnel : lien ou bouton si vous voulez rebasculer 
        sur la page de login 
      */}
      {mode === "register" && (
        <div className="login-link" onClick={() => navigateToLoginPage && navigateToLoginPage()}>
          Already Logged In User
        </div>
      )}
    </div>
  );
}

export default Register;
